  const appSecSuites = useMemo(() => {
    return QA_TEST_SUITES.filter(
      (suite) =>
        suite.category === QA_CATEGORIES.SECURITY ||
        (typeof suite.id === "string" && (suite.id.startsWith("SEC-") || suite.id.startsWith("CONC-")))
    );
  }, []);

  // Estatísticas e status de execução em tempo real
  const stats = useMemo(() => {
    let passed = 0;
    let failed = 0;
    let pending = 0;

    appSecSuites.forEach((t) => {
      const res = testResults[t.id];
      if (!res) {
        pending++;
      } else if (res.passed) {
        passed++;
      } else {
        failed++;
      }
    });

    const total = appSecSuites.length;
    const executed = passed + failed;
    const passRate = executed > 0 ? Math.round((passed / executed) * 100) : 0;
    const securityScore =
      executed > 0
        ? Math.round((passed / total) * 100)
        : 100; // Padrão 100 com testes prontos

    return {
      total,
      passed,
      failed,
      pending,
      executed,
      passRate,
      securityScore,
    };
  }, [appSecSuites, testResults]);

