{`// Validação com Proteção Anti-Replay em Memória (TTL 5 min)
export async function verifyTurnstileToken(token, options = {}) {
  cleanupConsumedTokens();

  if (!token || token.trim().length === 0) {
    return { success: false, errorCode: "MISSING_CAPTCHA_TOKEN", message: "CAPTCHA ausente." };
  }

  // Prevenção contra Replay Attack
  if (consumedTokensCache.has(token)) {
    return { success: false, errorCode: "TOKEN_ALREADY_CONSUMED", message: "Token já utilizado." };
  }

  // Registra token no cache para impedir reuso
  consumedTokensCache.set(token, Date.now());

  // Envio ao endpoint oficial do Cloudflare Turnstile
  const formData = new URLSearchParams({ secret: secretKey, response: token, remoteip: remoteIp });
  const response = await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify", {
    method: "POST",
    body: formData,
  });
  return await response.json();
}`}
