{`export function authRateLimitMiddleware(req, res, next) {
  const clientIp = req.headers["cf-connecting-ip"] || req.ip || "127.0.0.1";
  const identifier = req.body?.email || req.body?.username || "anonymous";

  const check = checkRateLimit({ identifier, ip: clientIp });

  // Injeção dos headers de rate limit na resposta HTTP
  Object.entries(check.headers).forEach(([header, val]) => res.setHeader(header, val));

  if (!check.allowed) {
    return res.status(429).json({
      error: "TOO_MANY_REQUESTS",
      message: check.message,
      retryAfterSeconds: check.retryAfterSeconds,
    });
  }

  next();
}`}
