{`// src/components/ui/SafeHtml.jsx
import React, { useMemo } from "react";
import DOMPurify from "dompurify";

export function SafeHtml({ html = "", as: Component = "div", className = "", config = {}, fallback = null, ...props }) {
  const sanitizedContent = useMemo(() => {
    if (!html || typeof html !== "string") return "";
    return DOMPurify.sanitize(html, {
      ALLOWED_TAGS: ["b", "i", "em", "strong", "a", "p", "br", "ul", "ol", "li", "span", "code", "pre"],
      ALLOWED_ATTR: ["href", "title", "target", "rel", "class"],
      FORBID_TAGS: ["script", "style", "iframe", "object", "embed", "svg"],
      FORBID_ATTR: ["onerror", "onload", "onclick", "javascript:"],
      ...config,
    });
  }, [html, config]);

  if (!sanitizedContent) return fallback ? <>{fallback}</> : null;

  return (
    <Component
      className={className}
      dangerouslySetInnerHTML={{ __html: sanitizedContent }}
      {...props}
    />
  );
}`}
