{`-- Extrai o tenant_id da claim JWT ou da tabela de associação
CREATE OR REPLACE FUNCTION public.get_auth_tenant_id()
RETURNS TEXT LANGUAGE plpgsql SECURITY DEFINER STABLE AS $$
DECLARE v_tenant_id TEXT;
BEGIN
  v_tenant_id := (auth.jwt() ->> 'tenant_id');
  IF v_tenant_id IS NOT NULL AND v_tenant_id <> '' THEN RETURN v_tenant_id; END IF;
  RETURN (auth.jwt() -> 'app_metadata' ->> 'tenant_id');
END; $$;

-- Determina se o usuário é SuperAdmin da plataforma
CREATE OR REPLACE FUNCTION public.is_superadmin()
RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER STABLE AS $$
BEGIN
  RETURN ((auth.jwt() ->> 'role') = 'SUPERADMIN' OR
          (auth.jwt() -> 'app_metadata' ->> 'role') = 'SUPERADMIN');
END; $$;`}
