{`BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap;
SELECT plan(20);

-- Grupo 1: RLS habilitada em todas as tabelas e buckets (6 asserções)
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid = 'public.barbershops'::regclass), 'barbershops RLS');
...
-- Grupo 3: Papel anon - Bloqueio total sem JWT (7 asserções)
SET ROLE anon;
SELECT results_eq('SELECT count(*)::int FROM public.appointments', ARRAY[0], 'anon appointments = 0');
SELECT throws_ok($$INSERT INTO public.appointments ...$$, '42501', NULL, 'anon insert rejects 42501');

-- Grupo 4: Isolamento Multi-Tenant Alpha vs Beta (6 asserções)
SET ROLE authenticated;
SET request.jwt.claim.tenant_id = '11111111-1111-1111-1111-111111111111';
SELECT results_eq('SELECT count(*)::int FROM public.appointments WHERE tenant_id = ''...''', ARRAY[1]);

-- Grupo 5: SuperAdmin - Visão global (1 asserção)
SELECT results_eq('SELECT count(*)::int >= 2 FROM public.appointments', ARRAY[true]);

SELECT * FROM finish();
ROLLBACK;`}
