{`export function validateSchemaMiddleware(schemaOptions: SchemaValidationOptions) {
  return (req: any, res: any, next: (err?: any) => void) => {
    const result = validateRequestData(req, schemaOptions);

    if (!result.success) {
      return res.status(400).json(result.errorResponse);
    }

    // Substituição segura dos dados brutos pelos dados validados com .strip()
    if (result.sanitizedData?.body) req.body = result.sanitizedData.body;
    if (result.sanitizedData?.query) req.query = result.sanitizedData.query;
    if (result.sanitizedData?.params) req.params = result.sanitizedData.params;

    next();
  };
}`}
