{`-- ==============================================================================
-- TASK 1.1: CAMADA DE DDL & PERFORMANCE (TABELA CUSTOMERS)
-- ==============================================================================

-- 1. Adição da coluna deleted_at na tabela de clientes
ALTER TABLE public.customers ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ DEFAULT NULL;

-- 2. Índices Parciais de Alta Performance (Otimização para Registros Ativos)
-- Otimiza 99% das consultas cotidianas ignorando registros soft-deleted do índice
CREATE INDEX IF NOT EXISTS idx_customers_active_tenant 
  ON public.customers (tenant_id, id) 
  WHERE deleted_at IS NULL;

-- Otimiza buscas rápidas por telefone ou e-mail de clientes ativos
CREATE INDEX IF NOT EXISTS idx_customers_active_lookup 
  ON public.customers (tenant_id, phone, email) 
  WHERE deleted_at IS NULL;

-- Índice para acelerar a rotina de expurgo e monitoramento de registros descontinuados
CREATE INDEX IF NOT EXISTS idx_customers_deleted_at 
  ON public.customers (deleted_at) 
  WHERE deleted_at IS NOT NULL;`}
