                    <pre className="p-4 bg-neutral-900 rounded-lg text-neutral-300 text-[11px] overflow-x-auto max-h-96 leading-relaxed border border-neutral-800 select-all font-mono">
{`name: DevSecOps Automated Security Audit (SAST, Secret Scanning & SCA)

on:
  pull_request:
    branches: [main, master, develop]
    paths-ignore:
      - '**.md'
      - 'docs/**'
  push:
    branches: [main, master]
    paths-ignore:
      - '**.md'
      - 'docs/**'
  workflow_dispatch:

permissions:
  contents: read
  security-events: write
  actions: read
  pull-requests: write

concurrency:
  group: \${{ github.workflow }}-\${{ github.ref }}
  cancel-in-progress: true

jobs:
  # =========================================================================
  # JOB 1: SECRET SCANNING (Gitleaks & TruffleHog)
  # =========================================================================
  secret-scanning:
    name: [BLINDAGEM] Secret Scanning (Gitleaks & TruffleHog)
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - name: Checkout Code with Complete History
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Run Gitleaks Detection
        uses: zricethezav/gitleaks-action@v2
        env:
          GITHUB_TOKEN: \${{ secrets.GITHUB_TOKEN }}
          GITLEAKS_CONFIG: .gitleaks.toml
        continue-on-error: false

      - name: Run TruffleHog Deep History Scan
        uses: trufflesecurity/trufflehog@main
        with:
          path: ./
          base: \${{ github.event.repository.default_branch }}
          head: HEAD
          extra_args: --debug --only-verified=false --fail
        continue-on-error: false

  # =========================================================================
  # JOB 2: STATIC APPLICATION SECURITY TESTING (SAST - Semgrep & SonarCloud)
  # =========================================================================
  sast-analysis:
    name: [BUSCA] Static Application Security Testing (Semgrep & SonarCloud)
    runs-on: ubuntu-latest
    timeout-minutes: 15
    steps:
      - name: Checkout Code
        uses: actions/checkout@v4

      - name: Run Semgrep SAST Analysis
        uses: returntocorp/semgrep-action@v1
        with:
          config: >-
            p/security-audit
            p/owasp-top-ten
            p/javascript
            p/react
            p/typescript
            p/secrets
          generateSarif: "1"
        env:
          SEMGREP_RULES: "p/owasp-top-ten p/security-audit"
        continue-on-error: false

  # =========================================================================
  # JOB 3: SOFTWARE COMPOSITION ANALYSIS (SCA - npm audit & Snyk)
  # =========================================================================
  dependency-audit:
    name: [PACOTE] Dependency Vulnerability Audit (npm audit & Snyk)
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - name: Checkout Code
        uses: actions/checkout@v4

      - name: Setup Node.js Environment
        uses: actions/setup-node@v4
        with:
          node-version: 20
          cache: "npm"

      - name: Run npm audit (Strict High & Critical Gate)
        run: npm audit --audit-level=high

  # =========================================================================
  # JOB 4: DEVSECOPS CONSOLIDATED QUALITY GATE VERDICT
  # =========================================================================
  security-gate-verdict:
    name: [CONFORMIDADE] DevSecOps Security Gate Verdict (Merge Blocker)
    needs: [secret-scanning, sast-analysis, dependency-audit]
    runs-on: ubuntu-latest
    if: always()
    steps:
      - name: Evaluate Security Scan Verdicts
        run: |
          if [ "\${{ needs.secret-scanning.result }}" != "success" ] || \\
             [ "\${{ needs.sast-analysis.result }}" != "success" ] || \\
             [ "\${{ needs.dependency-audit.result }}" != "success" ]; then
            echo "[REPROVADO] ERRO: Vulnerabilidades High/Critical detectadas. Merge bloqueado."
            exit 1
          fi
          echo "[APROVADO] SUCESSO: Todos os testes aprovados. Código liberado para merge."
          exit 0`}
                    </pre>
